contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(uint256 amount) public returns (bool) {
        require(amount > 0);
        c.AdjustBetAmounts(amount);
        assert(c.currentBetLimit() != 0);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(address nonOwner, uint256 newLimit) public {
        require(nonOwner != address(0) && nonOwner != address(this));
        c.OpenToThePublic{from: nonOwner}();
        bool revertBefore = (gasleft() == 0);
        try c.AdjustBetAmounts(newLimit) { revertBefore = false; } catch { revertBefore = true; }
        assert(revertBefore);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);
        c.donate{value: amount}();
        bool reverted; try c.AdjustBetAmounts(amount) { reverted = false; } catch { reverted = true; }
        assert(msg.sender == c.owner() ? !reverted : reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount, address nonOwner) public payable {
        require(nonOwner != address(0));
        require(nonOwner != tx.origin);
        c.donate{value: amount}();
        bool reverted; try c.AdjustBetAmounts(amount) { reverted = false; } catch { reverted = true; }
        assert(!reverted || msg.sender != tx.origin);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(true);
        bool isOwner = (caller == c.owner());
        bool reverted; try c.AdjustBetAmounts(100) { reverted = false; } catch { reverted = true; }
        assert(reverted || isOwner);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
